-- ===========================================================================
-- Hand-written below: what Prisma cannot express.
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- The money asked for (Q33): subtotal + VAT + delivery, nothing added for
-- Paystack's charge, and never nothing at all. The amount Paystack must
-- confirm is `totalKobo`, so a row whose parts disagree with it is refused
-- here as well as never written by the service.
-- ---------------------------------------------------------------------------
ALTER TABLE "Checkout"
  ADD CONSTRAINT "Checkout_money_check" CHECK (
    "subtotalKobo" >= 0
    AND "totalKobo" > 0
    AND "vatKobo" >= 0
    AND "deliveryKobo" >= 0
    AND "vatBps" >= 0
    AND "totalKobo" = "subtotalKobo" + "vatKobo" + "deliveryKobo"
  );

-- Pickup has no zone and no fee; a delivery names its zone. The address
-- lines are not held here: a deleted account's checkouts lose them (Q36)
-- while keeping the zone the fee was charged for.
ALTER TABLE "Checkout"
  ADD CONSTRAINT "Checkout_fulfilment_check" CHECK (
    ("fulfilment" = 'PICKUP' AND "zone" IS NULL AND "deliveryKobo" = 0)
    OR ("fulfilment" = 'DELIVERY' AND "zone" IS NOT NULL)
  );

-- A chosen slot has its instant; as soon as possible has none.
ALTER TABLE "Checkout"
  ADD CONSTRAINT "Checkout_timing_check"
  CHECK (("timing" = 'SCHEDULED') = ("scheduledFor" IS NOT NULL));

-- The reference CNC chooses (`cnc-order-<uuid>`), so a reference read from
-- a webhook can never match a row it did not make.
ALTER TABLE "Checkout"
  ADD CONSTRAINT "Checkout_reference_check"
  CHECK ("reference" ~ '^cnc-order-[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$');

-- The phone as CNC stores one (`0` plus 10 digits) and the email lower case,
-- or both empty once the customer deleted their account (Q36).
ALTER TABLE "Checkout"
  ADD CONSTRAINT "Checkout_contact_check" CHECK (
    ("contactPhone" ~ '^0[0-9]{10}$' OR "contactPhone" = '')
    AND "contactEmail" = lower("contactEmail")
  );

-- A paid checkout records when Paystack says it was paid.
ALTER TABLE "Checkout"
  ADD CONSTRAINT "Checkout_paid_check"
  CHECK ("status" <> 'PAID' OR "paidAt" IS NOT NULL);
